import { useEffect, useState } from "react";
import ProgressBar from "../components/ProgressBar";
import ProgressChart from "../components/ProgressChart";

export default function ProgressPage() {
  const [metrics, setMetrics] = useState({
    consistency: 0,
    quiz: 0,
    tasks: 0,
  });
  const [streak, setStreak] = useState(0);
  const [xp, setXP] = useState(0);
  const [level, setLevel] = useState(1);
  const [badges, setBadges] = useState([]);
  const [completedDays, setCompletedDays] = useState([]);
  const [recommendation, setRecommendation] = useState("");

  useEffect(() => {
    // 📊 DATA
    const quizScore = parseInt(localStorage.getItem("quizScore") || "0");
    const totalQuestions = parseInt(localStorage.getItem("totalQuestions") || "1");

    const completed = parseInt(localStorage.getItem("lastCompletedCount") || "0");
    const totalTasks = parseInt(localStorage.getItem("lastTotalTasks") || "1");

    const storedCompletedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");
    const currentDay = parseInt(localStorage.getItem("currentDay") || "1");

    // 📈 CALCULATIONS
    const quizPercentage = Math.round((quizScore / totalQuestions) * 100);
    const taskPercentage = Math.round((completed / totalTasks) * 100);
    const consistency = Math.round((storedCompletedDays.length / currentDay) * 100);

    // 🔥 STREAK
    let currentStreak = 0;
    const sortedDays = [...storedCompletedDays].sort((a, b) => a - b);

    for (let i = sortedDays.length - 1; i >= 0; i--) {
      if (sortedDays[i] === currentDay - currentStreak - 1) currentStreak++;
      else break;
    }

    // 🎮 XP + LEVEL
    const totalXP = parseInt(localStorage.getItem("xp") || "0");
    const userLevel = Math.floor(totalXP / 100) + 1;

    // 🏅 BADGES
    const badgeList = [];
    if (currentStreak >= 3) badgeList.push("🔥 3 Day Streak");
    if (currentStreak >= 7) badgeList.push("🚀 7 Day Warrior");
    if (quizPercentage >= 80) badgeList.push("🧠 Quiz Master");
    if (consistency >= 70) badgeList.push("📅 Consistency King");
    if (totalXP >= 500) badgeList.push("🏆 Level Grinder");

    // 🤖 RECOMMENDATION
    const generateRecommendation = () => {
      if (taskPercentage < 50) return "⚡ Focus on completing daily tasks consistently.";
      if (quizPercentage < 60) return "🧠 Revise fundamentals and reattempt quizzes.";
      if (consistency < 70) return "📅 Try to maintain a daily learning streak.";
      if (taskPercentage > 80 && quizPercentage > 80) return "🚀 You're ahead! Start building projects.";
      return "👍 You're doing well. Keep improving steadily.";
    };

    // ✅ SET STATE
    setMetrics({
      consistency,
      quiz: quizPercentage,
      tasks: taskPercentage,
    });
    setStreak(currentStreak);
    setXP(totalXP);
    setLevel(userLevel);
    setBadges(badgeList);
    setCompletedDays(storedCompletedDays);
    setRecommendation(generateRecommendation());

  }, []);

  return (
    <div className="space-y-6 max-w-7xl mx-auto">

  {/* HEADER */}
  <div className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-white to-blue-50 p-6 shadow-md dark:border-slate-700 dark:from-slate-800 dark:to-slate-800">
    <h2 className="text-2xl font-semibold text-slate-900 dark:text-slate-50">
      📊 Progress Dashboard
    </h2>
    <p className="text-sm text-slate-600 dark:text-slate-400">
      Track your learning performance and growth
    </p>
  </div>

  {/* XP + LEVEL */}
  <div className="grid gap-4 sm:grid-cols-2">
    <div className="rounded-[1.5rem] border border-slate-300 bg-gradient-to-br from-purple-100 to-purple-50 p-5 shadow-sm dark:border-slate-700 dark:from-slate-800 dark:to-slate-800">
      <p className="text-xs text-slate-500 dark:text-slate-400">Total XP</p>
      <p className="text-2xl font-bold text-purple-700 dark:text-purple-300">{xp}</p>
    </div>

    <div className="rounded-[1.5rem] border border-slate-300 bg-gradient-to-br from-green-100 to-green-50 p-5 shadow-sm dark:border-slate-700 dark:from-slate-800 dark:to-slate-800">
      <p className="text-xs text-slate-500 dark:text-slate-400">Level</p>
      <p className="text-2xl font-bold text-green-700 dark:text-green-300">
        {level}
      </p>
    </div>
  </div>

  {/* GRAPH + STREAK */}
  <div className="grid gap-4 lg:grid-cols-2">

    <div className="rounded-[1.5rem] border border-slate-300 bg-gradient-to-br from-white to-blue-50 p-5 shadow-sm dark:border-slate-700 dark:from-slate-800 dark:to-slate-800">
      <h3 className="text-sm font-medium text-slate-700 light:text-slate-300">
        📈 Weekly Progress
      </h3>
      <div className="mt-4">
        <ProgressChart completedDays={completedDays} />
      </div>
    </div>

    <div className="rounded-[1.5rem] bg-gradient-to-br from-teal-100 to-blue-100 p-5 shadow-sm dark:from-slate-800 dark:to-slate-800">
      <p className="text-xs text-slate-600 dark:text-slate-400">Streak</p>
      <p className="text-3xl font-bold text-teal-900 dark:text-teal-300">
        {streak} days
      </p>
    </div>

  </div>

  {/* METRICS */}
  <div className="grid gap-4 md:grid-cols-3">
    <div className="rounded-[1.5rem] border border-slate-300 bg-white p-4 shadow-sm dark:border-slate-700 dark:bg-slate-800">
      <ProgressBar label="Consistency" value={metrics.consistency} />
    </div>

    <div className="rounded-[1.5rem] border border-slate-300 bg-white p-4 shadow-sm dark:border-slate-700 dark:bg-slate-800">
      <ProgressBar label="Quiz" value={metrics.quiz} />
    </div>

    <div className="rounded-[1.5rem] border border-slate-300 bg-white p-4 shadow-sm dark:border-slate-700 dark:bg-slate-800">
      <ProgressBar label="Tasks" value={metrics.tasks} />
    </div>
  </div>

  {/* AI + BADGES */}
  <div className="grid gap-4 lg:grid-cols-2">

    <div className="rounded-[1.5rem] bg-gradient-to-br from-yellow-100 to-orange-50 p-5 shadow-sm dark:from-slate-800 dark:to-slate-800">
      <p className="text-sm font-medium text-slate-700 dark:text-slate-300">
        🤖 Recommendation
      </p>
      <p className="text-sm mt-2 text-slate-600 dark:text-slate-400">
        {recommendation}
      </p>
    </div>

    <div className="rounded-[1.5rem] border border-slate-300 bg-gradient-to-br from-white to-blue-50 p-5 shadow-sm dark:border-slate-700 dark:from-slate-800 dark:to-slate-800">
      <p className="text-sm font-medium text-slate-700 dark:text-slate-300">
        🏅 Achievements
      </p>

      <div className="mt-3 flex flex-wrap gap-2">
        {badges.length > 0 ? (
          badges.map((badge, i) => (
            <span
              key={i}
              className="text-xs px-3 py-1 rounded-full bg-teal-500 text-white"
            >
              {badge}
            </span>
          ))
        ) : (
          <p className="text-xs text-slate-500">No badges yet</p>
        )}
      </div>
    </div>

  </div>

</div>
  );
}
